package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.repository.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/webhooks") public class WebhookController { private final WebhookSubscriptionRepository subscriptions; private final CustomerRepository customers; public WebhookController(WebhookSubscriptionRepository subscriptions,CustomerRepository customers){this.subscriptions=subscriptions;this.customers=customers;} record SubscriptionRequest(Long customerId,@NotBlank @Pattern(regexp="https?://.+") String targetUrl,@NotBlank @Size(min=16) String secret){} @PostMapping("/subscriptions") ResponseEntity<WebhookSubscription> create(@RequestBody @jakarta.validation.Valid SubscriptionRequest request){WebhookSubscription w=new WebhookSubscription();w.setTargetUrl(request.targetUrl());w.setSecret(request.secret());if(request.customerId()!=null)w.setCustomer(customers.findById(request.customerId()).orElseThrow());return ResponseEntity.status(HttpStatus.CREATED).body(subscriptions.save(w));} @PostMapping("/mock-receiver") Map<String,Object> mock(@RequestHeader(value="X-Webhook-Signature",required=false) String signature,@RequestBody Map<String,Object> payload){return Map.of("received",true,"eventId",payload.get("eventId"),"signaturePresent",signature!=null);} }
